export type RegionName = "forehead" | "leftCheek" | "rightCheek" | "chin" | "nose";
export type Poly = [number, number][];
export type Mark = { x: number; y: number; r: number };
export type Sensitivity = "low" | "normal" | "high";
export type SkinMetrics = {
  v: 1 | 2 | 3;
  redness: { forehead: number | null; leftCheek: number | null; rightCheek: number | null; chin: number | null; mean: number | null };
  spots: { forehead: number; leftCheek: number; rightCheek: number; chin: number; total: number };
  oil: number | null;
  brightness: number;
  coverage: Record<string, number>;
  sensitivity?: Sensitivity;
  quality?: Quality;
  marks?: Record<string, Mark[]>;
  at?: string;
};
export const SENSITIVITY: Record<Sensitivity, number>;
export type Pose = { yaw: number; pitch: number; roll: number };
export type Quality = { pose: Pose | null; faceWidth: number; sharp: number; wb: boolean; gains: number[] | null; warnings: string[] };
export const EYE_POINTS: { left: number[]; right: number[] };
export function scleraIndices(landmarks: Poly, width: number, height: number): number[];
export function whiteBalanceGains(data: Uint8ClampedArray, idx: number[]): number[] | null;
export function sharpness(data: Uint8ClampedArray, width: number, height: number, box: { x0: number; y0: number; x1: number; y1: number }): number;
export function poseFromMatrix(d: ArrayLike<number> | null | undefined): Pose | null;
export function poseFromLandmarks(p: Poly): Pose;
export function qualityWarnings(q?: { yaw?: number; pitch?: number; faceWidth?: number; brightness?: number; sharp?: number; wb?: boolean }): string[];
export function mergeBlobs(a: Mark[], b: Mark[]): Mark[];
export function rgbToLab(r: number, g: number, b: number): [number, number, number];
export const REGION_POINTS: Record<RegionName, number[]>;
export const REGION_LABEL: Record<RegionName, string>;
export const SKIN_REGIONS: ("forehead" | "leftCheek" | "rightCheek" | "chin")[];
export function convexHull(points: Poly): Poly;
export function shrink(poly: Poly, k: number): Poly;
export function regionPolygons(landmarks: Poly, k?: number): Record<RegionName, Poly>;
export function faceWidthOf(landmarks: Poly): number;
export function maskOf(poly: Poly, width: number, height: number): number[];
export function countSpots(A: Float32Array, L: Float32Array, idx: number[], width: number, r: number, opts?: { z?: number; minDelta?: number; minArea?: number; maxArea?: number }): { count: number; blobs: Mark[] };
export function analyzePixels(image: { data: Uint8ClampedArray; width: number; height: number }, polys: Record<string, Poly>, faceWidth: number, opts?: { sensitivity?: Sensitivity; gains?: number[] | null }): SkinMetrics;
export function deltas(now: SkinMetrics | null | undefined, prev: SkinMetrics | null | undefined): { redness: number | null; spots: number | null; oil: number | null; brightness: number | null } | null;
